<script setup lang="ts">
import EnCard from '@/Components/EnCard.vue';
import EnInput from '@/Components/EnInput.vue';
import SuperAdminSidePanel from '@/Components/SuperAdminSidePanel.vue';
import { Head, useForm } from '@inertiajs/vue3';
import { ref } from 'vue';

type User = { id: number; name: string; username: string; email: string; tenant?: { name: string } | null };
const props = defineProps<{ users: { data: User[] }; plans: Array<{ id: number; name: string }> }>();
const form = useForm({ name: '', username: '', email: '', password: '', business_name: '', slug: '', plan_id: props.plans[0]?.id ?? '' });
const editingId = ref<number | null>(null);
const editingForm = useForm({ name: '', username: '', email: '', password: '' });
const submit = (): void => form.post(route('super-admin.users.store'), { onSuccess: () => form.reset('name', 'username', 'email', 'password', 'business_name', 'slug') });
const editUser = (user: User): void => { editingId.value = user.id; editingForm.name = user.name; editingForm.username = user.username; editingForm.email = user.email; editingForm.password = ''; };
const updateUser = (): void => { if (editingId.value !== null) editingForm.patch(route('super-admin.users.update', { user: editingId.value }), { onSuccess: () => { editingId.value = null; } }); };
</script>
<template>
    <Head title="Workspace users" />
    <main class="flex min-h-screen bg-neutral-50 text-neutral-900"><SuperAdminSidePanel current="users" /><section class="min-w-0 flex-1 px-5 py-8 sm:px-10"><header><p class="text-sm font-semibold text-[#e21b23]">User administration</p><h1 class="mt-1 text-3xl font-black">Workspace users</h1><p class="mt-2 text-neutral-500">Create login details and provision Online Store and POS access through a subscription plan.</p></header><div class="mt-8 grid gap-8 xl:grid-cols-[400px_1fr]"><EnCard><h2 class="text-lg font-bold">Add a new user</h2><form class="mt-5 space-y-4" @submit.prevent="submit"><EnInput id="user-name" v-model="form.name" label="Full name" required /><EnInput id="user-username" v-model="form.username" label="Username" required /><EnInput id="user-email" v-model="form.email" type="email" label="Email" required /><EnInput id="user-password" v-model="form.password" type="password" label="Password" required /><EnInput id="business-name" v-model="form.business_name" label="Business name" required /><EnInput id="business-slug" v-model="form.slug" label="Store URL slug" required /><label class="block text-sm font-medium text-neutral-700">Subscription plan<select v-model="form.plan_id" class="mt-1 min-h-11 w-full rounded-md border border-neutral-300 bg-white px-3 text-sm"><option v-for="plan in plans" :key="plan.id" :value="plan.id">{{ plan.name }}</option></select></label><button type="submit" class="w-full rounded-md bg-[#e21b23] px-4 py-3 text-sm font-bold text-white disabled:opacity-60" :disabled="form.processing">Create workspace user</button></form></EnCard><EnCard><h2 class="text-lg font-bold">Existing users</h2><div class="mt-5 overflow-x-auto"><table class="w-full text-left text-sm"><thead class="border-b border-neutral-200 text-xs uppercase text-neutral-500"><tr><th class="px-3 py-3">Name</th><th class="px-3 py-3">Username</th><th class="px-3 py-3">Workspace</th><th class="px-3 py-3">Email</th><th></th></tr></thead><tbody><tr v-for="user in users.data" :key="user.id" class="border-b border-neutral-100"><td class="px-3 py-4 font-semibold">{{ user.name }}</td><td class="px-3 py-4">{{ user.username }}</td><td class="px-3 py-4">{{ user.tenant?.name ?? 'Unassigned' }}</td><td class="px-3 py-4">{{ user.email }}</td><td class="px-3 py-4 text-right"><button type="button" class="font-semibold text-[#e21b23]" @click="editUser(user)">Edit</button></td></tr></tbody></table></div><form v-if="editingId !== null" class="mt-6 border-t border-neutral-200 pt-5" @submit.prevent="updateUser"><h3 class="font-bold">Edit login details</h3><div class="mt-4 grid gap-4 sm:grid-cols-2"><EnInput id="edit-user-name" v-model="editingForm.name" label="Full name" required /><EnInput id="edit-user-username" v-model="editingForm.username" label="Username" required /><EnInput id="edit-user-email" v-model="editingForm.email" type="email" label="Email" required /><EnInput id="edit-user-password" v-model="editingForm.password" type="password" label="New password (optional)" /></div><button type="submit" class="mt-4 rounded-md bg-[#171717] px-4 py-2 text-sm font-bold text-white" :disabled="editingForm.processing">Save changes</button></form></EnCard></div></section></main>
</template>
